def sha(b):return hashlib.sha256(b).hexdigest()
def check(root=R):
 run=root/(root/'CURRENT').read_text().strip();d=json.loads((run/'result.json').read_text());assert (run/'result.json').read_bytes()==(run/'stdout.json').read_bytes()
 assert json.loads((root/'requests.json').read_text())==REQUESTS
 oracle=json.loads((root/'oracle.json').read_text());assert oracle['requests']==REQUESTS and oracle['expected']==EXPECTED
 assert oracle['correctCounterfactual']=={'leaf-only-fault':{'result':'EACCES','firstStop':{'node':'/vault','stage':'SEARCH'}}}
 for n,h in d['sourceHashes'].items():assert sha((root/n).read_bytes())==h,n
 for n,v in json.loads((run/'artifacts.json').read_text())['files'].items():
  b=(run/n).read_bytes();assert sha(b)==v['sha256'] and len(b)==v['bytes'],n
 assert [c['id'] for c in d['cases']]==list(REQUESTS)
 for c in d['cases']:
  n=c['id'];x=REQUESTS[n];folder=run/n;inp=x['rawInput'].encode() if 'rawInput' in x else (json.dumps(x,sort_keys=True)+'\n').encode()
  assert (folder/'input.txt').read_bytes()==inp and c['inputSha256']==sha(inp)
  assert (folder/'stdout.txt').read_text()==c['stdout'] and (folder/'stderr.txt').read_text()==c['stderr'] and json.loads((folder/'command.json').read_text())==c
  assert c['argv']==['python3','-B','../walker.py'] and c['startedUtc']<=c['endedUtc']
  if n=='execution-failure':assert c['exitCode']==3 and c['stdout']=='' and c['stderr'].startswith('JSONDecodeError:') and c['observation'] is None and c['outcome']=='EXECUTION_FAILURE';continue
  assert c['stderr']=='' and json.loads(c['stdout'])==c['observation']==EXPECTED[n],n
  assert c['exitCode']==(2 if n.startswith('refused-') else 0) and c['outcome']==('REFUSED' if n.startswith('refused-') else 'OBSERVED')
 return len(d['cases'])
if __name__=='__main__':print('PASS '+str(check())+' conditions; independent literal class/gate/firstStop/decision; no producer import')
